// The TypeScript surface of the buyer-facing renderer. The WASM module under
// ../wasm is generated by `cargo xtask build-web` and is not checked in.
import init, { version, type InitInput } from "../wasm/cavea_web.js";

/**
 * A WebGL2 seat view on a canvas. Construct it only after `loadRenderer()` has
 * resolved. Interim surface for the demo; the public SDK is `docs/05-web-sdk.md`.
 */
export { View } from "../wasm/cavea_web.js";
export { attach, type AttachOptions, type Attached, type GestureHandling } from "./host.ts";

/** The loaded renderer. */
export interface Renderer {
  /** Version of the Rust renderer build that was loaded. */
  version(): string;
}

/**
 * Where to load the WASM from. Omit it to fetch the module that ships next to
 * this package; pass a URL, a `Response`, bytes or a compiled module to load it
 * from elsewhere.
 */
export type WasmSource = InitInput;

let loading: Promise<Renderer> | undefined;

/**
 * Loads and instantiates the renderer's WASM once; later calls share the result.
 * After a failed load the next call tries again.
 */
export function loadRenderer(source?: WasmSource): Promise<Renderer> {
  loading ??= init({
    module_or_path: source ?? new URL("../wasm/cavea_web_bg.wasm", import.meta.url),
  }).then(
    () => ({ version }),
    (error: unknown) => {
      loading = undefined;
      throw error;
    },
  );
  return loading;
}
